extracted = {"corp": "가상전자", "period": "2026Q3", "revenue": 1000,
             "operating_income": 120, "net_income": 150, "unit": "억원"}
problems = []
for key in ["corp", "period", "revenue", "operating_income", "net_income", "unit"]:
    if key not in extracted:
        problems.append("빠진 칸 " + key)
if extracted["unit"] not in ("원", "백만원", "억원"):
    problems.append("단위 모름")
if extracted["operating_income"] > extracted["revenue"]:
    problems.append("영업이익 > 매출")
if abs(extracted["net_income"]) > 2 * abs(extracted["operating_income"]):
    problems.append("순이익이 영업이익의 2배 넘음 - 원문 대조")
print(problems or "통과")
