from decimal import Decimal as D
vendor_a = {"005930": D("12.30"), "000660": D("4.10"), "035420": D("20.0")}
vendor_b = {"005930": D("12.31"), "000660": D("5.20"), "035720": D("48.0")}
tol = D("0.01")
for k in sorted(set(vendor_a) | set(vendor_b)):
    a, b = vendor_a.get(k), vendor_b.get(k)
    if a is None or b is None:
        print(k, "한쪽에만 있음", a, b)
    elif abs(a - b) / max(abs(a), abs(b)) > tol:
        print(k, "값 다름", a, b)
    else:
        print(k, "일치")
# 000660 값 다름 4.10 5.20
# 005930 일치
# 035420 한쪽에만 있음 20.0 None
# 035720 한쪽에만 있음 None 48.0

def isin_ok(isin):
    if len(isin) != 12:
        return False
    digits = "".join(str(int(c, 36)) for c in isin[:-1])
    total = 0
    for i, ch in enumerate(reversed(digits)):
        n = int(ch)
        if i % 2 == 0:
            n *= 2
            if n > 9:
                n -= 9
        total += n
    return (10 - total % 10) % 10 == int(isin[-1])

for code in ["US0378331005", "KR7005930003", "KR7005930004"]:
    print(code, isin_ok(code))
# US0378331005 True
# KR7005930003 True
# KR7005930004 False
